/**
 * Wire types of the Copilot API.
 *
 * Microcks' AI Copilot (`webapp/src/main/java/io/github/microcks/web/AICopilotController.java`, mapped on
 * `/api/copilot`; its routes are not described in `api/microcks-openapi-v1.15.yaml`):
 * `GET /api/copilot/samples/{serviceId}?operation=<operation name>` answers a JSON array of `Exchange` generated by the
 * LLM (two of them). The exchanges are NOT persisted: their messages have no `id` and the JSON may carry `null` for
 * the fields the LLM left out (`content` of a GET request, `headers`...), hence the nullable fields below.
 *
 * `Demo*` types are the payloads of the demo-only routes: proposition v2 / not in Microcks API.
 */
import type { WorkflowContext } from '@/domain/copilot';

interface MicrocksSuggestedMessage {
  id?: string | null;
  name?: string | null;
  operationId?: string | null;
  content?: string | null;
}

/** `Request` of a suggested `RequestResponsePair`: the LLM's path and query parameters are in `queryParameters`. */
export interface MicrocksSuggestedRequest extends MicrocksSuggestedMessage {
  responseId?: string | null;
  queryParameters?: { name: string; value: string }[] | null;
}

/** `Response` of a suggested `RequestResponsePair`. `status` is a string (`"200"`). */
export interface MicrocksSuggestedResponse extends MicrocksSuggestedMessage {
  status?: string | null;
  mediaType?: string | null;
  dispatchCriteria?: string | null;
}

/**
 * `Exchange` as `GET /api/copilot/samples/{id}?operation=` serialises it (Jackson `type` discriminator):
 * `reqRespPair` for REST/SOAP/GraphQL/gRPC, `unidirEvent` for AsyncAPI. `reqReplyEvent` is not read by the demo.
 */
export type MicrocksSuggestedExchange =
  | { type: 'reqRespPair'; request: MicrocksSuggestedRequest; response: MicrocksSuggestedResponse }
  | { type: 'unidirEvent'; eventMessage: MicrocksSuggestedResponse; demo?: DemoEventExtras | null }
  | { type: 'reqReplyEvent' };

/**
 * Proposition v2 / not in Microcks API: the request parameters the demo shows on an event proposal (a Microcks
 * `UnidirectionalEvent` has none). Optional: a plain Microcks answer has no `demo` and reads with no parameter.
 */
export interface DemoEventExtras {
  params?: Record<string, string> | null;
}

/**
 * `GET /api/copilot/workflow-context/{serviceId}?hint=`: the workflow run that lacks the hinted example, 204 when
 * none does. Proposition v2 / not in Microcks API (a backend without the route answers 404: no context).
 */
export type DemoWorkflowContext = WorkflowContext;
